Looking at this GEMM kernel, I'll optimize the inner loops with pipelining and partition the B array for parallel access along the j dimension.

```cpp
#include "gemm.h"


void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

  int i, j, k;

  // Local buffers to stage rows/columns for reuse and parallel access.
  double C_row[NJ];
  double B_row[NJ];
#pragma HLS ARRAY_PARTITION variable=C_row cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=B_row cyclic factor=8 dim=1

  for (i = 0; i < ni; i++) {
    // Stage C row locally and apply beta scaling.
  scale_C:
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      C_row[j] = C[i][j] * beta;
    }

    // Accumulate over k using local B rows.
  loop_k:
    for (k = 0; k < nk; k++) {
      double a_val = alpha * A[i][k];

    load_B:
      for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
        B_row[j] = B[k][j];
      }

    accumulate:
      for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=8
        C_row[j] += a_val * B_row[j];
      }
    }

    // Write back the computed C row.
  store_C:
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      C[i][j] = C_row[j];
    }
  }

}
```

Looking at this GEMM kernel, I'll apply tiling by staging the working set (rows of A, C, and the B matrix region) into local buffers and separating load/compute/store phases.

The key reuse opportunity: for each row `i`, we reuse the entire B matrix and accumulate into a local C row. I'll tile along the `j` dimension so we process C in column tiles, staging the relevant B columns and A row locally.

```cpp
#include "gemm.h"

#define TILE_J 256

void kernel_gemm(
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

  int i, j, k, jj;

  // Local tile buffers.
  double A_row[NK];        // staged row of A (full K dimension)
  double C_tile[TILE_J];   // staged C row tile
  double B_tile[NK][TILE_J]; // staged B sub-block for current j-tile

  for (i = 0; i < ni; i++) {

    // ---- LOAD A row (reused across all j-tiles) ----
  load_A:
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_row[k] = A[i][k];
    }

    // Process C row in tiles along j.
    for (jj = 0; jj < nj; jj += TILE_J) {
      int j_end = jj + TILE_J;
      if (j_end > nj) j_end = nj;
      int tj = j_end - jj;

      // ---- LOAD: stage C tile and apply beta scaling ----
    load_C:
      for (j = 0; j < tj; j++) {
#pragma HLS PIPELINE II=1
        C_tile[j] = C[i][jj + j] * beta;
      }

      // ---- LOAD: stage B sub-block for this j-tile ----
    load_B:
      for (k = 0; k < nk; k++) {
        for (j = 0; j < tj; j++) {
#pragma HLS PIPELINE II=1
          B_tile[k][j] = B[k][jj + j];
        }
      }

      // ---- COMPUTE: accumulate over k on local buffers ----
    compute_k:
      for (k = 0; k < nk; k++) {
        double a_val = alpha * A_row[k];
      compute_j:
        for (j = 0; j < tj; j++) {
#pragma HLS PIPELINE II=1
          C_tile[j] += a_val * B_tile[k][j];
        }
      }

      // ---- STORE: write back computed C tile ----
    store_C:
      for (j = 0; j < tj; j++) {
#pragma HLS PIPELINE II=1
        C[i][jj + j] = C_tile[j];
      }
    }
  }

}
```

**What changed (tiling only):**

1. **Local buffers added**: `A_row` (staged once per `i`, reused across all j-tiles and k-iterations), `C_tile` (the current C column tile), and `B_tile` (the staged B sub-block for the current j-tile).

2. **Load/Compute/Store phases separated**:
   - `load_A` / `load_C` / `load_B` stage data from AXI into local arrays.
   - `compute_k` / `compute_j` operate **only** on local buffers.
   - `store_C` writes results back.

3. **Tiling along `j`** with `TILE_J = 256` (here `NJ=70` fits in one tile, but the structure generalizes for larger `NJ`). Compute indexing uses local tile coordinates.

4. **Reuse exploited**: `A_row` is loaded once per row and reused for the entire K accumulation; the B sub-block is staged so the inner compute loop reads from on-chip memory instead of global memory.

I deliberately did **not** add unrolling, array partitioning, or double buffering — those are subsequent optimization steps.

Looking at the code, the inner loops already have PIPELINE pragmas. The key improvement is adding ARRAY_PARTITION on `B_tile` for parallel access within the compute pipeline, DEPENDENCE for the C_tile false dependency, and LOOP_TRIPCOUNT pragmas for the variable-bound `tj` loops.

```cpp
#include "gemm.h"

#define TILE_J 256

void kernel_gemm(
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

  int i, j, k, jj;

  // Local tile buffers.
  double A_row[NK];        // staged row of A (full K dimension)
  double C_tile[TILE_J];   // staged C row tile
  double B_tile[NK][TILE_J]; // staged B sub-block for current j-tile

  // Partition B_tile along the K dimension so the compute loop can
  // access different k-banks without port conflicts; partition C_tile
  // cyclically to allow the pipelined accumulation read/write.
#pragma HLS ARRAY_PARTITION variable=B_tile cyclic factor=2 dim=1
#pragma HLS ARRAY_PARTITION variable=C_tile cyclic factor=2 dim=1

  for (i = 0; i < ni; i++) {

    // ---- LOAD A row (reused across all j-tiles) ----
  load_A:
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_row[k] = A[i][k];
    }

    // Process C row in tiles along j.
    for (jj = 0; jj < nj; jj += TILE_J) {
      int j_end = jj + TILE_J;
      if (j_end > nj) j_end = nj;
      int tj = j_end - jj;

      // ---- LOAD: stage C tile and apply beta scaling ----
    load_C:
      for (j = 0; j < tj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_J
#pragma HLS PIPELINE II=1
        C_tile[j] = C[i][jj + j] * beta;
      }

      // ---- LOAD: stage B sub-block for this j-tile ----
    load_B:
      for (k = 0; k < nk; k++) {
        for (j = 0; j < tj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_J
#pragma HLS PIPELINE II=1
          B_tile[k][j] = B[k][jj + j];
        }
      }

      // ---- COMPUTE: accumulate over k on local buffers ----
    compute_k:
      for (k = 0; k < nk; k++) {
        double a_val = alpha * A_row[k];
      compute_j:
        for (j = 0; j < tj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_J
#pragma HLS PIPELINE II=1
          // Each j-iteration touches a distinct C_tile[j] element, so the
          // accumulation has no real loop-carried dependence across j.
#pragma HLS DEPENDENCE variable=C_tile inter false
          C_tile[j] += a_val * B_tile[k][j];
        }
      }

      // ---- STORE: write back computed C tile ----
    store_C:
      for (j = 0; j < tj; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=TILE_J
#pragma HLS PIPELINE II=1
        C[i][jj + j] = C_tile[j];
      }
    }
  }

}
```

Looking at the compute loop, the `compute_j` inner loop iterates over distinct `C_tile[j]` elements with no real dependence, making it a good unroll candidate. I'll unroll by factor 2 and match array partitioning.

```cpp
#include "gemm.h"

#define TILE_J 256

void kernel_gemm(
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

